"use client";

import { useState } from "react";
import useProducts from "@/hooks/useProducts";
import Navbar from "@/components/common/Navbar";

const ProductListing = () => {
  const {
    products,
    categories,
    currentPage,
    setCurrentPage,
    totalPages,
    loading,
    selectedCategory,
    setSelectedCategory,
    searchQuery,
    setSearchQuery,
    sortOption,
    setSortOption,
    sortDirection,
    setSortDirection,
  } = useProducts();

  return (
    <>
      <Navbar />
      <div className="p-8">
        {/* Filters */}
        <div className="flex space-x-4 mb-6">
          <input
            type="text"
            placeholder="Search by product name"
            className="border p-2 rounded w-1/3"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />

          <select
            className="border p-2 rounded"
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
          >
            <option value="">All Categories</option>
            {categories.map((category) => (
              <option key={category.categoryId} value={category.categoryName}>
                {category.categoryName}
              </option>
            ))}
          </select>

          <select
            className="border p-2 rounded"
            value={sortOption}
            onChange={(e) => setSortOption(e.target.value)}
          >
            <option value="createdAt">Newest</option>
            <option value="price">Price</option>
          </select>

          <select
            className="border p-2 rounded"
            value={sortDirection}
            onChange={(e) => setSortDirection(e.target.value)}
          >
            <option value="ASC">Ascending</option>
            <option value="DESC">Descending</option>
          </select>
        </div>

        {/* Product List */}
        {loading ? (
          <p>Loading...</p>
        ) : (
          <div className="grid grid-cols-4 gap-4">
            {Array.isArray(products) && products.length > 0 ? (
              products.map((product) => (
                <div key={product.productId} className="border p-4 rounded">
                  <img
                    src={
                      Array.isArray(product.productPictures) && product.productPictures.length > 0
                        ? product.productPictures[0].productPictureUrl
                        : "placeholder.jpg"
                    }
                    alt={product.productName}
                    className="w-full h-40 object-cover mb-2"
                  />
                  <h2 className="text-lg font-bold">{product.productName}</h2>
                  <p className="text-green-600">Rp. {product.price.toLocaleString("id-ID")}</p>
                </div>
              ))
            ) : (
              <p>No products available</p>
            )}
          </div>
        )}

        {/* Pagination */}
        <div className="flex justify-center mt-6">
          <button
            className="border p-2 mx-2"
            disabled={currentPage === 1}
            onClick={() => setCurrentPage((prev) => prev - 1)}
          >
            Prev
          </button>
          <span className="p-2">Page {currentPage} of {totalPages}</span>
          <button
            className="border p-2 mx-2"
            disabled={currentPage === totalPages}
            onClick={() => setCurrentPage((prev) => prev + 1)}
          >
            Next
          </button>
        </div>
      </div>
    </>
  );
};

export default ProductListing;
