"use client"; // Add this at the top

import { useState, useEffect } from "react";

interface Product {
  productId: number;
  productName: string;
  detail: string;
  price: number;
  weight: number;
  totalStock: number;
  productCategory: string;
  productPictures: { productPictureUrl: string; position: number } | null;
}

interface Category {
  categoryId: number;
  categoryName: string;
}

interface ApiResponse {
  content: Product[];
  totalPages: number;
  number: number;
}

const useProducts = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>("");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [sortOption, setSortOption] = useState<string>("createdAt");
  const [sortDirection, setSortDirection] = useState<string>("ASC");

  useEffect(() => {
    const fetchProducts = async () => {
      setLoading(true);
      try {
        const response = await fetch(
          `http://localhost:8080/api/v1/products?page=${currentPage - 1}&name=${searchQuery}&category=${selectedCategory}&sortField=${sortOption}&sortDirection=${sortDirection}`
        );
        const data: ApiResponse = await response.json();
        setProducts(data.content);
        setTotalPages(data.totalPages);
      } catch (error) {
        console.error("Error fetching products:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, [currentPage, searchQuery, selectedCategory, sortOption, sortDirection]);

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await fetch("http://localhost:8080/api/v1/categories");
        const data = await response.json();
        setCategories(data.data);
      } catch (error) {
        console.error("Error fetching categories:", error);
      }
    };

    fetchCategories();
  }, []);

  return {
    products,
    categories,
    currentPage,
    setCurrentPage,
    totalPages,
    loading,
    selectedCategory,
    setSelectedCategory,
    searchQuery,
    setSearchQuery,
    sortOption,
    setSortOption,
    sortDirection,
    setSortDirection,
  };
};

export default useProducts;